pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint64 ts1, uint64 ts2) public {
        // Ensure timestamps are different so the delayed write matters
        vm.assume(ts1 != ts2);

        // First call with ts1
        vm.prank(0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001);
        c.setL1BlockValues(0, ts1, 0, bytes32(0), 0, bytes32(0), 0, 0);

        // Second call with ts2
        vm.prank(0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001);
        c.setL1BlockValues(0, ts2, 0, bytes32(0), 0, bytes32(0), 0, 0);

        // After two calls, the public timestamp getter must return the last _timestamp (ts2)
        assertTrue(c.timestamp() == ts2);
    }
}
